import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

// ConvTranspose3d specialized for:
//   kernel = 3x3x3, stride = 1, padding = 0, output_padding = 0,
//   dilation = 1, groups = 1, dtype = float32
//   in  : (N, 48, 96, 96, 96)  contiguous
//   w   : (48, 24, 3, 3, 3)    contiguous  (in_ch, out_ch, kD, kH, kW)
//   bias: (24,) or dummy
//   out : (N, 24, 98, 98, 98)  contiguous
// out[b,oc,z,y,x] = sum_{ic,kz,ky,kx} w[ic,oc,2-kz,2-ky,2-kx]
//                   * in[b,ic,z+kz-2,y+ky-2,x+kx-2]   (zero outside input)
//                 + bias[oc] (optional)

.visible .entry conv_transpose3d_k3_s1(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 total,
    .param .u32 has_bias
)
{
    .reg .pred  %p<12>;
    .reg .b32   %r<40>;
    .reg .b64   %rd<24>;
    .reg .f32   %f<8>;

    ld.param.u64 %rd0, [in_ptr];
    ld.param.u64 %rd1, [w_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.u32 %r0,  [total];
    ld.param.u32 %r1,  [has_bias];

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.u32 %r5, %r2, %r3, %r4;          // idx = global linear output index
    setp.ge.u32 %p0, %r5, %r0;
    @%p0 bra DONE;                          // partial-block bounds check

    // decode idx -> b(r10), oc(r11), z(r12), y(r13), x(r14)
    rem.u32 %r14, %r5, 98;
    div.u32 %r6,  %r5, 98;
    rem.u32 %r13, %r6, 98;
    div.u32 %r6,  %r6, 98;
    rem.u32 %r12, %r6, 98;
    div.u32 %r6,  %r6, 98;
    rem.u32 %r11, %r6, 24;
    div.u32 %r10, %r6, 24;

    // tap bounds: klo = max(0, 2 - coord), khi = min(2, 97 - coord)
    mov.s32 %r15, 2;
    sub.s32 %r15, %r15, %r12;
    max.s32 %r15, %r15, 0;                  // kz_lo
    mov.s32 %r16, 97;
    sub.s32 %r16, %r16, %r12;
    min.s32 %r16, %r16, 2;                  // kz_hi

    mov.s32 %r17, 2;
    sub.s32 %r17, %r17, %r13;
    max.s32 %r17, %r17, 0;                  // ky_lo
    mov.s32 %r18, 97;
    sub.s32 %r18, %r18, %r13;
    min.s32 %r18, %r18, 2;                  // ky_hi

    mov.s32 %r19, 2;
    sub.s32 %r19, %r19, %r14;
    max.s32 %r19, %r19, 0;                  // kx_lo
    mov.s32 %r20, 97;
    sub.s32 %r20, %r20, %r14;
    min.s32 %r20, %r20, 2;                  // kx_hi

    mov.f32 %f0, 0f00000000;                // accumulator
    mov.u32 %r21, 0;                        // ic = 0

IC_LOOP:
    setp.ge.u32 %p1, %r21, 48;
    @%p1 bra IC_DONE;

    // rd4 = in + (b*48 + ic) * 884736 * 4   (input plane base)
    mad.lo.u32 %r22, %r10, 48, %r21;
    mul.lo.u32 %r22, %r22, 884736;
    mul.wide.u32 %rd5, %r22, 4;
    add.s64 %rd4, %rd0, %rd5;

    // rd6 = w + (ic*24 + oc) * 27 * 4       (weight kernel base)
    mad.lo.u32 %r23, %r21, 24, %r11;
    mul.lo.u32 %r23, %r23, 27;
    mul.wide.u32 %rd7, %r23, 4;
    add.s64 %rd6, %rd1, %rd7;

    mov.s32 %r24, %r15;                     // kz = kz_lo
KZ_LOOP:
    setp.gt.s32 %p2, %r24, %r16;
    @%p2 bra KZ_DONE;
    add.s32 %r25, %r12, %r24;
    sub.s32 %r25, %r25, 2;                  // iz = z + kz - 2
    mul.lo.u32 %r26, %r25, 36864;           // iz * 96 * 96 * 4
    cvt.u64.u32 %rd8, %r26;
    add.s64 %rd9, %rd4, %rd8;               // input slice base

    mov.s32 %r27, %r17;                     // ky = ky_lo
KY_LOOP:
    setp.gt.s32 %p3, %r27, %r18;
    @%p3 bra KY_DONE;
    add.s32 %r28, %r13, %r27;
    sub.s32 %r28, %r28, 2;                  // iy = y + ky - 2

    // rd11 = slice + (iy*96 + x + kx_lo - 2) * 4
    mad.lo.u32 %r29, %r28, 96, %r14;
    add.s32 %r29, %r29, %r19;
    sub.s32 %r29, %r29, 2;
    mul.lo.u32 %r29, %r29, 4;
    cvt.u64.u32 %rd10, %r29;
    add.s64 %rd11, %rd9, %rd10;

    // flipped weight tap base: (26 - (kz*9 + ky*3 + kx_lo)) * 4
    mul.lo.u32 %r30, %r24, 9;
    mad.lo.u32 %r30, %r27, 3, %r30;
    add.s32 %r30, %r30, %r19;
    mov.u32 %r32, 26;
    sub.s32 %r30, %r32, %r30;
    mul.lo.u32 %r30, %r30, 4;
    cvt.u64.u32 %rd12, %r30;
    add.s64 %rd13, %rd6, %rd12;

    mov.s32 %r31, %r19;                     // kx = kx_lo
KX_LOOP:
    setp.gt.s32 %p4, %r31, %r20;
    @%p4 bra KX_DONE;
    ld.global.f32 %f1, [%rd11];
    ld.global.f32 %f2, [%rd13];
    fma.rn.f32 %f0, %f1, %f2, %f0;
    add.s64 %rd11, %rd11, 4;                // next input column
    sub.s64 %rd13, %rd13, 4;                // previous (flipped) weight tap
    add.s32 %r31, %r31, 1;
    bra KX_LOOP;
KX_DONE:
    add.s32 %r27, %r27, 1;
    bra KY_LOOP;
KY_DONE:
    add.s32 %r24, %r24, 1;
    bra KZ_LOOP;
KZ_DONE:
    add.s32 %r21, %r21, 1;
    bra IC_LOOP;
IC_DONE:

    setp.eq.u32 %p5, %r1, 0;
    @%p5 bra STORE;
    mul.wide.u32 %rd14, %r11, 4;
    add.s64 %rd15, %rd2, %rd14;
    ld.global.f32 %f3, [%rd15];             // bias[oc]
    add.f32 %f0, %f0, %f3;

STORE:
    mul.wide.u32 %rd16, %r5, 4;
    add.s64 %rd17, %rd3, %rd16;
    st.global.f32 [%rd17], %f0;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_k3_s1")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(in_channels, out_channels, (kernel_size, kernel_size, kernel_size),
                                                   stride=stride, padding=padding, output_padding=output_padding,
                                                   dilation=dilation, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        conv = self.conv_transpose3d
        x = x.contiguous()
        weight = conv.weight.contiguous()

        n, cin, d, h, w = x.shape
        kd, kh, kw = conv.kernel_size
        d_out = (d - 1) * conv.stride[0] - 2 * conv.padding[0] + conv.dilation[0] * (kd - 1) + conv.output_padding[0] + 1
        h_out = (h - 1) * conv.stride[1] - 2 * conv.padding[1] + conv.dilation[1] * (kh - 1) + conv.output_padding[1] + 1
        w_out = (w - 1) * conv.stride[2] - 2 * conv.padding[2] + conv.dilation[2] * (kw - 1) + conv.output_padding[2] + 1

        out = torch.empty((n, conv.out_channels, d_out, h_out, w_out), device=x.device, dtype=x.dtype)

        if conv.bias is not None:
            bias_arg = conv.bias.contiguous()
            has_bias = 1
        else:
            bias_arg = weight
            has_bias = 0

        total = out.numel()
        block = 256
        grid_x = (total + block - 1) // block

        module = _get_ptx_module()
        module.launch(
            "conv_transpose3d_k3_s1",
            grid=(grid_x, 1, 1),
            block=(block, 1, 1),
            arguments=[x, weight, bias_arg, out, i32(total), i32(has_bias)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

